test('separate endpoint families resolve negative stepped T/corners and hidden one metre neighbours before alpha mixing',()=>{
 const {prepareTerrainFamily,terrainPreparedFamilyGradient,terrainPackBasis,terrainPackDraft,preparedWorkBytes}=api;
 for(const shift of [0,-10_000_384]){
  const boxes=[[-512,-512,512],[0,-512,256],[0,-256,128],[0,-128,128],[0,0,1024],[0,-3,1],[0,-5,1]];
  const models=(a,b)=>boxes.map(([x,y,width],id)=>({object:{id:`family-${id}`},grid:{view:{box:{x:shift+x,y:shift+y,width,height:width},columns:65,rows:65},heights:Float64Array.from({length:4225},(_,i)=>a*Math.max(0,x+i%65*width/64)**2+b*Math.max(0,y+Math.floor(i/65)*width/64)**2)}}));
  const families=[[1,1],[-2,3],[3,-1]].map(([a,b])=>drain(prepareTerrainFamily(models(a,b),()=>{})).value);
  for(const f of families){assert.equal(f.cache.xySupport.length/3,f.nodeIds.size);assert.equal(preparedWorkBytes(f.cache),100*f.nodeIds.size);}
  // At the corner physical support16 gives (16^2-0)/(2*16)=8.
  // The coarse left edge's native y=-8 node has (4,0). Its affine
  // interpolation to y=0 therefore gives these independently derived values.
  for(const [y,gx,gy] of [[0,8,8],[-8,4,0],[-4,6,4],[-2.5,6.75,5.5],[-4.5,5.75,3.5]]){
   const p={x:shift,y:shift+y},expected=[[gx,gy],[-2*gx,3*gy],[3*gx,gy===0?0:-gy]],actual=families.map(f=>terrainPreparedFamilyGradient(f,p));assert.deepEqual(actual,expected);
   // Both actual source-edge partitions must produce that same affine value,
   // including the tiny neighbour between two coarse eight-metre nodes.
   for(let family=0;family<families.length;family++)for(const slot of [0,...(y===-2.5?[5]:y===-4.5?[6]:[3])]){const f=families[family],m=f.models[slot],b=m.grid.view.box,step=b.height/64,row=Math.min(63,Math.floor((p.y-b.y)/step)),weight=(p.y-b.y)/step-row,edge=slot===0?64:0,ids=[row,row+1].map(r=>f.nodeIds.get(`${p.x}/${b.y+r*step}`)),value=[0,0];assert(ids.every(i=>i!==undefined));for(let c=0;c<2;c++)value[c]=f.gradients[ids[0]*2+c]*(1-weight)+f.gradients[ids[1]*2+c]*weight;assert.deepEqual(value,expected[family]);assert.equal(edge===0||edge===64,true);}
   const packed=new Float32Array(14),draft=new Float32Array(6);terrainPackBasis(packed,0,[0,0],{height:0,gradientX:actual[0][0],gradientY:actual[0][1]},{height:0,gradientX:actual[1][0],gradientY:actual[1][1]});terrainPackDraft(draft,0,{height:0,gradientX:actual[2][0],gradientY:actual[2][1]});for(const alpha of [0,.5,1]){const value=terrainEvaluateVertex(packed,draft,0,alpha,0),expectedX=gx*(6-3*alpha),expectedY=gy*(-3+2*alpha)||0;assert.equal(value.gradientX,expectedX);assert.equal(value.gradientY,expectedY);}
  }
 }
});

